public class SafeOIS extends ObjectInputStream {
    private static final Set<String> ALLOWED = Set.of(
        "java.lang.String", "java.util.ArrayList", "java.util.HashMap");
    public SafeOIS(InputStream in) throws IOException { super(in); }
    @Override
    protected Class<?> resolveClass(ObjectStreamClass desc)
            throws IOException, ClassNotFoundException {
        if (!ALLOWED.contains(desc.getName()))
            throw new InvalidClassException("Blocked", desc.getName());
        return super.resolveClass(desc);
    }
}

