function safeMerge(t, s) {
  for (let k of Object.keys(s)) {
    if (k === '__proto__' || k === 'constructor' || k === 'prototype') continue;
    if (typeof s[k] === 'object' && s[k] !== null && !Array.isArray(s[k])) {
      t[k] = safeMerge(t[k] || {}, s[k]);
    } else { t[k] = s[k]; }
  }
  return t;
}

